            return a.labels.indexOf('ai_validated') !== -1; }),
            'failure side never latches ai_validated — the fail path owns it');
        assert.ok(sm.capturedPrLabelAdds.some(function (a) {
            return a.labels.indexOf('validation_failed') !== -1; }),
