 * speaks the same contract), so this source is forge-portable as-is.
 *
 * Item shape:
 *   { key: 'gh-125' | 'pr-127', labels, pr: {number,state,checks,mergeState,
 *     mergeable} | null, issueNumber, prNumber }
 */
