        var sm = makeSmAgent(Object.assign(config('a', 'b'), {
            github: {
                items: [prItem(82, { labels: ['pr_approved', 'ai_validated'], branch: 'feat/w', headSha: 'shaNEW' })],
                prStatus: { checkConclusion: 'green' },
