        sm.action({ jobParams: { owner: 'a', repo: 'b', rules: [RULES.sweep] } });

        assert.deepEqual(sm.capturedPrLabelRemoves.map(function (r) { return r.number + ':' + r.label; }),
            ['85:ai_validating'], 'the stale arm is released');
