        ['review-after-dev', 'review-external-once', 'review-on-label'].forEach(function (id) {
            assert.ok(byId[id], id + ' exists');
            assert.ok(!byId[id].query.prMachineAuthor, id + ': review stays open to all authors');
        });
    });

