                         labels: (t.fields && t.fields.labels) || t.labels || [],
                         pr: null, issueNumber: null, prNumber: null };
            });
        }
    };
    // Optional github source stub: opts.github = { items: [...], pr: {...} } —
    // for close-on-merge (localAction) and PR-lifecycle (#687) rule tests.
    if (opts.github) {
