            assert.equal(r.source, 'github', r.id + ' must declare source: github');
            assert.ok(r.query, r.id + ' needs a query object');
            assert.ok(r.configFile || r.inputs || r.localAction,
                r.id + ' needs configFile, inputs, or localAction');
        });
    });

